//! Strongly typed ISO 20022 (MX) messages, generated from the official XSDs.
//!
//! Every message type in this crate will be generated by
//! [`iso-20022-codegen`](https://github.com/tilli-pro/financial-messaging/tree/main/crates/iso-20022-codegen)
//! from the XML Schema published in the ISO 20022 catalogue, and is meant to
//! be **correct by construction**: a value that type-checks is a value the
//! schema accepts.
//!
//! - Code lists become Rust enums, so an unknown code cannot be represented.
//! - Facets (length, pattern, digits, ranges) become validated newtypes whose
//!   only constructor checks the facet.
//! - Cardinalities become typed containers: `1..1` is a plain field, `0..1`
//!   an `Option`, `1..n` a non-empty collection, bounded `n..m` a collection
//!   that checks its bounds.
//!
//! Serialization and deserialization use `serde` and `quick-xml`, and every
//! generated message is round-tripped and checked against an independent XSD
//! validator in the test suite.
//!
//! # Status
//!
//! Pre-release. Only [`MessageIdentifier`] exists today; no message types have
//! been generated yet. Nothing has been published to crates.io.
//!
//! # Example
//!
//! ```
//! use iso_20022::MessageIdentifier;
//!
//! let id = MessageIdentifier::parse("pacs.008.001.08")?;
//! assert_eq!(id.business_area(), "pacs");
//! assert_eq!(id.message_functionality(), 8);
//! assert_eq!(id.variant(), 1);
//! assert_eq!(id.version(), 8);
//! assert_eq!(id.to_string(), "pacs.008.001.08");
//! # Ok::<(), iso_20022::MessageIdentifierError>(())
//! ```

#![forbid(unsafe_code)]
#![deny(missing_docs)]

use core::fmt;

/// An ISO 20022 message identifier: `area.functionality.variant.version`,
/// for example `pacs.008.001.08`.
///
/// - business area: four lowercase ASCII letters (`pacs`, `pain`, `camt`, ...)
/// - message functionality: three digits
/// - variant: three digits (`001` is the base message)
/// - version: two digits
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct MessageIdentifier {
    business_area: [u8; 4],
    message_functionality: u16,
    variant: u16,
    version: u8,
}

/// Why a string is not a valid ISO 20022 message identifier.
#[derive(Debug, Clone, Copy, PartialEq, Eq, thiserror::Error)]
pub enum MessageIdentifierError {
    /// The identifier does not have exactly four dot-separated segments.
    #[error("message identifier must have 4 dot-separated segments, got {0}")]
    Segments(usize),
    /// The business area is not four lowercase ASCII letters.
    #[error("business area must be 4 lowercase ASCII letters")]
    BusinessArea,
    /// The message functionality is not three ASCII digits.
    #[error("message functionality must be 3 ASCII digits")]
    MessageFunctionality,
    /// The variant is not three ASCII digits.
    #[error("variant must be 3 ASCII digits")]
    Variant,
    /// The version is not two ASCII digits.
    #[error("version must be 2 ASCII digits")]
    Version,
}

impl MessageIdentifier {
    /// Parses an identifier of the form `area.functionality.variant.version`.
    ///
    /// # Errors
    ///
    /// Returns a [`MessageIdentifierError`] naming the first segment that is
    /// missing or malformed.
    pub fn parse(input: &str) -> Result<Self, MessageIdentifierError> {
        let segments: Vec<&str> = input.split('.').collect();
        let [area, functionality, variant, version] = segments.as_slice() else {
            return Err(MessageIdentifierError::Segments(segments.len()));
        };

        let area = area.as_bytes();
        let business_area: [u8; 4] = area
            .try_into()
            .ok()
            .filter(|a: &[u8; 4]| a.iter().all(u8::is_ascii_lowercase))
            .ok_or(MessageIdentifierError::BusinessArea)?;

        let message_functionality =
            digits(functionality, 3).ok_or(MessageIdentifierError::MessageFunctionality)?;
        let variant = digits(variant, 3).ok_or(MessageIdentifierError::Variant)?;
        let version = digits(version, 2)
            .and_then(|v| u8::try_from(v).ok())
            .ok_or(MessageIdentifierError::Version)?;

        Ok(Self {
            business_area,
            message_functionality,
            variant,
            version,
        })
    }

    /// The four-letter business area, for example `pacs`.
    #[must_use]
    pub fn business_area(&self) -> &str {
        // Always ASCII: `parse` is the only constructor and checks it.
        core::str::from_utf8(&self.business_area).unwrap_or_default()
    }

    /// The message functionality, for example `8` in `pacs.008.001.08`.
    #[must_use]
    pub const fn message_functionality(&self) -> u16 {
        self.message_functionality
    }

    /// The variant, for example `1` in `pacs.008.001.08`.
    #[must_use]
    pub const fn variant(&self) -> u16 {
        self.variant
    }

    /// The version, for example `8` in `pacs.008.001.08`.
    #[must_use]
    pub const fn version(&self) -> u8 {
        self.version
    }
}

/// Parses exactly `len` ASCII digits.
fn digits(s: &str, len: usize) -> Option<u16> {
    let bytes = s.as_bytes();
    if bytes.len() != len || !bytes.iter().all(u8::is_ascii_digit) {
        return None;
    }
    Some(
        bytes
            .iter()
            .fold(0u16, |acc, b| acc * 10 + u16::from(b - b'0')),
    )
}

impl fmt::Display for MessageIdentifier {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "{}.{:03}.{:03}.{:02}",
            self.business_area(),
            self.message_functionality,
            self.variant,
            self.version
        )
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn parses_first_message_set() {
        for s in [
            "pain.001.001.09",
            "pain.002.001.10",
            "pacs.008.001.08",
            "pacs.002.001.10",
            "pacs.004.001.09",
            "camt.053.001.08",
            "camt.054.001.08",
            "camt.056.001.08",
        ] {
            assert_eq!(MessageIdentifier::parse(s).unwrap().to_string(), s);
        }
    }

    #[test]
    fn exposes_segments() {
        let id = MessageIdentifier::parse("camt.053.001.08").unwrap();
        assert_eq!(id.business_area(), "camt");
        assert_eq!(id.message_functionality(), 53);
        assert_eq!(id.variant(), 1);
        assert_eq!(id.version(), 8);
    }

    #[test]
    fn rejects_malformed() {
        use MessageIdentifierError as E;
        let cases = [
            ("", E::Segments(1)),
            ("pacs.008.001", E::Segments(3)),
            ("pacs.008.001.08.1", E::Segments(5)),
            ("PACS.008.001.08", E::BusinessArea),
            ("pac.008.001.08", E::BusinessArea),
            ("pacs.08.001.08", E::MessageFunctionality),
            ("pacs.0x8.001.08", E::MessageFunctionality),
            ("pacs.008.1.08", E::Variant),
            ("pacs.008.001.8", E::Version),
            ("pacs.008.001.008", E::Version),
        ];
        for (input, expected) in cases {
            assert_eq!(MessageIdentifier::parse(input), Err(expected), "{input}");
        }
    }

    proptest! {
        #[test]
        fn round_trip(
            area in "[a-z]{4}",
            functionality in 0u16..=999,
            variant in 0u16..=999,
            version in 0u8..=99,
        ) {
            let s = format!("{area}.{functionality:03}.{variant:03}.{version:02}");
            let id = MessageIdentifier::parse(&s).unwrap();
            prop_assert_eq!(id.business_area(), area.as_str());
            prop_assert_eq!(id.message_functionality(), functionality);
            prop_assert_eq!(id.variant(), variant);
            prop_assert_eq!(id.version(), version);
            prop_assert_eq!(MessageIdentifier::parse(&id.to_string()).unwrap(), id);
            prop_assert_eq!(id.to_string(), s);
        }
    }
}
